def split_csv(line):
    fields = []
    i = 0
    n = len(line)
    while True:
        if i < n and line[i] == '"':
            # quoted field
            i += 1
            chars = []
            closed = False
            while i < n:
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i+1] == '"':
                        chars.append('"')
                        i += 2
                        continue
                    else:
                        i += 1
                        closed = True
                        break
                else:
                    chars.append(c)
                    i += 1
            if not closed:
                return None
            # after closing quote, must be comma or end of line
            if i < n:
                if line[i] == ',':
                    fields.append(''.join(chars))
                    i += 1
                    if i == n:
                        fields.append('')
                        break
                    continue
                else:
                    return None
            else:
                fields.append(''.join(chars))
                break
        else:
            # unquoted field
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    return None
                i += 1
            fields.append(line[start:i])
            if i < n and line[i] == ',':
                i += 1
                if i == n:
                    fields.append('')
                    break
                continue
            else:
                break
    return fields

